[{"order":1,"type":"heading","text":"Mastering Expo Router and File-Based Routing Paradigms in React Native"},{"order":2,"type":"paragraph","text":"Traditional React Native applications often rely on imperative routing libraries like React Navigation, requiring explicit route configuration and nested navigators. Expo Router brings a paradigm shift by introducing file-based routing, similar to Next.js, directly into the React Native ecosystem."},{"order":3,"type":"subheading","text":"Understanding the Directory Structure"},{"order":4,"type":"paragraph","text":"In an Expo Router project, the app directory acts as the root of your navigation tree. Every file inside this directory automatically becomes a route in your application based on its filename."},{"order":5,"type":"bullet_point","text":"app/index.tsx maps to the root URL (\/\)."},{"order":6,"type":"bullet_point","text":"app/profile.tsx maps to the \/profile route."},{"order":7,"type":"bullet_point","text":"app/(tabs)/_layout.tsx acts as a layout wrapper for tab-based navigation."},{"order":8,"type":"subheading","text":"Creating Your First Screen"},{"order":9,"type":"paragraph","text":"Let us create a basic screen inside the app directory. Expo Router uses standard React components for UI rendering."},{"order":10,"type":"code","text":"import { View, Text, StyleSheet } from 'react-native';
import { Link } from 'expo-router';

export default function HomeScreen() {
  return (
    <View style={styles.container}>
      <Text style={styles.title}>Welcome to Expo Router</Text>
      <Link href="/profile" style={styles.link}>Go to Profile</Link>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  title: { fontSize: 20, fontWeight: 'bold' },
  link: { marginTop: 16, color: 'blue' }
});"},{"order":11,"type":"subheading","text":"Dynamic Routes and Parameters"},{"order":12,"type":"paragraph","text":"File-based routing natively supports dynamic segments using bracket notation. For instance, creating a file named app/user/[id].tsx allows you to capture route parameters effortlessly using the useLocalSearchParams hook."},{"order":13,"type":"code","text":"import { View, Text } from 'react-native';
import { useLocalSearchParams } from 'expo-router';

export default function UserScreen() {
  const { id } = useLocalSearchParams();

  return (
    <View>
      <Text>User Profile ID: {id}</Text>
    </View>
  );
}"},{"order":14,"type":"subheading","text":"Summary"},{"order":15,"type":"paragraph","text":"By adopting Expo Router, developers can reduce boilerplate code, leverage native navigation primitives, and maintain a clean, intuitive project structure across iOS, Android, and Web platforms."}]
